"""Random request generator for differential testing against the reference."""

import random
import string


def rand_name(used, i):
    while True:
        name = string.ascii_uppercase[i % 26] + "".join(
            random.choice(string.ascii_lowercase) for _ in range(random.randint(0, 3)))
        if name not in used:
            used.add(name)
            return name


def make_topology(rng, nodes=5, ext=3, links=None):
    ids = list(range(nodes))
    used = set()
    names = {i: rand_name(used, i) for i in ids}
    pairs = set()
    # spanning tree-ish skeleton so the graph is connected most of the time
    order = ids[:]
    rng.shuffle(order)
    for a, b in zip(order, order[1:]):
        if rng.random() < 0.9:
            pairs.add((min(a, b), max(a, b)))
    extra = links if links is not None else rng.randint(0, nodes)
    for _ in range(extra):
        a, b = rng.choice(ids), rng.choice(ids)
        if a != b:
            pairs.add((min(a, b), max(a, b)))
    degree = {i: 0 for i in ids}
    out_links = []
    for a, b in pairs:
        if degree[a] >= 8 or degree[b] >= 8:
            continue
        degree[a] += 1
        degree[b] += 1
        out_links.append({"source": a, "target": b,
                          "capacity": rng.choice([0, 1, 10, 25, 50, 100, 10 ** 9])})
    externals = rng.sample(ids, min(ext, nodes))
    return {
        "nodes": [{"id": i, "name": names[i],
                   "external_capacity": rng.choice([0, 5, 20, 40, 100, 10 ** 9])}
                  for i in ids],
        "links": out_links,
        "external_nodes": [names[i] for i in externals],
    }, names, {(min(a, b), max(a, b)) for a, b in
               [(l["source"], l["target"]) for l in out_links]}, externals


def adjacency(links):
    adj = {}
    for link in links:
        adj.setdefault(link["source"], set()).add(link["target"])
        adj.setdefault(link["target"], set()).add(link["source"])
    return adj


def simple_paths(adj, src, dst, limit=4, maxlen=6):
    found = []
    stack = [[src]]
    while stack and len(found) < limit:
        path = stack.pop()
        last = path[-1]
        if last == dst:
            found.append(path)
            continue
        if len(path) >= maxlen:
            continue
        for nxt in sorted(adj.get(last, ())):
            if nxt not in path:
                stack.append(path + [nxt])
    return found


def make_routes(rng, topology, names):
    links = topology["links"]
    adj = adjacency(links)
    id_of = {v: k for k, v in names.items()}
    externals = [id_of[n] for n in topology["external_nodes"]]
    plan = {}
    for s in externals:
        row = {}
        for d in externals:
            if s == d:
                continue
            candidates = simple_paths(adj, s, d)
            if not candidates:
                return None
            chosen = rng.sample(candidates, min(len(candidates),
                                                rng.randint(1, 4)))
            count = len(chosen)
            weights = []
            left = 1000
            for i in range(count):
                if i == count - 1:
                    weights.append(left)
                else:
                    w = rng.randint(1, max(1, left - (count - i - 1)))
                    w = min(w, 1000 - (count - i - 1))
                    weights.append(w)
                    left -= w
            if weights[-1] < 1:
                return None
            row[names[d]] = [{"path": [names[v] for v in p], "weight": w}
                             for p, w in zip(chosen, weights)]
        plan[names[s]] = row
    return plan


def make_settings(rng):
    return {
        "trials": rng.randint(1, 4),
        "epsilon": rng.choice([0, 1, 999, 50000, 100000, 250000]),
        "seed": rng.randrange(0, 2 ** 32),
        "cutoff": [rng.randrange(0, 6), rng.choice([1, 2, 3, 7])],
        "bias": rng.choice([0, 1000, 24000, 1000000]),
        "tau": rng.choice([0, 1000, 100000, 1000000]),
        "gamma": rng.choice([[1, 1], [1, 2], [0, 1], [3, 2], [5, 2]]),
        "cache_slots": rng.randint(0, 3),
    }
