#!/usr/bin/env python3
"""Differential test: package vs literal reference on random streams."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tmp')

import reference  # noqa: E402
from crosscheck.crosscheck import CrossCheck  # noqa: E402
import gen  # noqa: E402


def package_answer(request):
    streams = []
    for stream in request["streams"]:
        engine = CrossCheck(stream["topology"])
        streams.append({"events": engine.replay(stream["events"], stream["settings"])})
    return {"streams": streams}


def build_events(rng, topology, names, externals, count, bad_rate=0.25):
    id_of = {v: k for k, v in names.items()}
    caps = {n["name"]: n["external_capacity"] for n in topology["nodes"]}
    link_cap = {}
    for link in topology["links"]:
        link_cap[frozenset((link["source"], link["target"]))] = link["capacity"]
    events = []
    counter_state = {}
    for _ in range(count):
        kind = rng.random()
        if kind < 0.40:
            counters = {}
            for link in topology["links"]:
                a, b = link["source"], link["target"]
                cap = link["capacity"]
                for key in (f"low_{names[a]}_egress_to_{names[b]}",
                            f"low_{names[b]}_ingress_from_{names[a]}"):
                    counters[key] = cell(rng, cap)
            for nid in externals:
                for key in (f"low_{names[nid]}_origination",
                            f"low_{names[nid]}_termination"):
                    counters[key] = cell(rng, caps[names[nid]])
            if rng.random() < 0.3:
                for key in list(counters)[:2]:
                    counters[key] = None
            demands = []
            for s in externals:
                for d in externals:
                    if s == d:
                        continue
                    bound = min(caps[names[s]], caps[names[d]])
                    demands.append([s, d, rng.randint(0, min(bound, 60)) if bound else 0])
            if rng.random() < 0.4:
                demands = demands[:max(1, len(demands) - 1)]
            event = {"op": "patch", "demands": demands, "counters": counters}
            if rng.random() < bad_rate:
                event = corrupt_patch(rng, event, topology, names, counters, demands)
            events.append(event)
        elif kind < 0.60:
            plan = None if rng.random() < 0.25 else gen.make_routes(rng, topology, names)
            events.append({"op": "routes", "label": "plan%d" % rng.randint(0, 9),
                           "paths": plan})
        elif kind < 0.85:
            events.append({"op": "repair", "id": "s%d" % rng.randint(0, 2)})
        else:
            events.append({"op": "validate", "id": "s%d" % rng.randint(0, 2)})
    return events


def cell(rng, cap):
    style = rng.random()
    if style < 0.2:
        return None
    if style < 0.35:
        return {"perturbed": None, "ground_truth": rng.randint(0, 3)}
    value = rng.randint(0, min(cap, 40)) if cap else 0
    payload = {"perturbed": value}
    if style < 0.5:
        payload["ground_truth"] = rng.choice([None, 7, {"a": [1, 2]}, "x", True])
        payload["confidence"] = rng.choice([None, [1, 2], 5])
        payload["corrected"] = rng.choice([None, 999, "ignore me"])
    return payload


def corrupt_patch(rng, event, topology, names, counters, demands):
    which = rng.randint(0, 6)
    event = json.loads(json.dumps(event))
    if which == 0:
        event["demands"].append([1, 1, 1])
    elif which == 1:
        event["demands"].append([0, 1, 10 ** 9])
    elif which == 2:
        event["counters"]["low_unknown_egress_to_x"] = {"perturbed": 1}
    elif which == 3:
        keys = list(event["counters"])
        if keys:
            event["counters"][keys[0]] = {"perturbed": True}
    elif which == 4:
        event["extra"] = 1
    elif which == 5:
        event["counters"] = []
    else:
        if demands:
            event["demands"].append(list(demands[0]))
    return event


def make_stream(rng, nodes=None, ext=None, events=6):
    topology, names, links, externals = gen.make_topology(
        rng, nodes or rng.randint(2, 5), ext or rng.randint(1, 3))
    settings = gen.make_settings(rng)
    id_of = {v: k for k, v in names.items()}
    ext_ids = [id_of[n] for n in topology["external_nodes"]]
    return {"topology": topology, "settings": settings,
            "events": build_events(rng, topology, names, ext_ids, events)}


def main(trials=400, seed=1):
    mismatches = 0
    for case in range(trials):
        rng = random.Random(seed * 100000 + case)
        stream = make_stream(rng)
        request = {"streams": [stream]}
        try:
            expected = reference.answer(request)
        except Exception as exc:
            print("reference crashed", case, exc)
            continue
        got = package_answer(request)
        if got != expected:
            mismatches += 1
            print("MISMATCH case", case)
            print(json.dumps(request))
            print("got     ", json.dumps(got)[:1500])
            print("expected", json.dumps(expected)[:1500])
            if mismatches >= 2:
                return 1
    print("done, mismatches:", mismatches, "of", trials)
    return 1 if mismatches else 0


if __name__ == "__main__":
    sys.exit(main(int(sys.argv[1]) if len(sys.argv) > 1 else 400))
